import{_ as r,C as a,o as i,c as u,j as s,a as c,E as n,a2 as o}from"./chunks/framework.BxGh02fV.js";const q=JSON.parse('{"title":"Connaissance","description":"","frontmatter":{"title":"Connaissance"},"headers":[],"relativePath":"guide/knowledge.md","filePath":"guide/knowledge.md"}'),l={name:"guide/knowledge.md"};function d(g,e,p,h,m,f){const t=a("Capture");return i(),u("div",null,[e[0]||(e[0]=s("h1",{id:"connaissance",tabindex:"-1"},[c("Connaissance "),s("a",{class:"header-anchor",href:"#connaissance","aria-label":'Permalink to "Connaissance"'},"​")],-1)),e[1]||(e[1]=s("p",null,"Cet écran réunit tout ce qui a été décidé et écrit pour le projet : décisions (ADR), questions ouvertes (BQO) et documents de cadrage. Vous y venez pour retrouver pourquoi un choix a été fait, ou pour consigner une décision.",-1)),n(t,{name:"connaissance",alt:"L'écran Connaissance : arbre de portée à gauche, décision DEC-01 à droite"}),e[2]||(e[2]=o('<h2 id="ce-que-vous-voyez" tabindex="-1">Ce que vous voyez <a class="header-anchor" href="#ce-que-vous-voyez" aria-label="Permalink to &quot;Ce que vous voyez&quot;">​</a></h2><ul><li><strong>Portée</strong> (colonne de gauche) : l&#39;arbre Projet, épics et stories, avec un champ <strong>Rechercher…</strong> et un filtre <strong>Statut</strong> (<strong>Tous</strong> / <strong>Masquer terminés</strong>). Cliquez sur un nœud pour limiter l&#39;écran à ce périmètre. La colonne se redimensionne à la souris.</li><li><strong>Fil d&#39;Ariane</strong> (en haut à droite) : <code>Projet › Epic … › Story …</code>, le périmètre affiché.</li><li><strong>Rechercher dans la lentille…</strong> : filtre le contenu affiché. Le raccourci <code>/</code> ou <code>Cmd/Ctrl+F</code> place le curseur dans ce champ.</li><li><strong>Les lentilles</strong> (onglets) : une par type de contenu, avec son compteur — <strong>Décisions (ADR)</strong>, <strong>Questions (BQO)</strong>, et celles qui lisent les documents de cadrage : Cadrage projet (au niveau Projet), Glossaire, Analyse, Architecture, Specs, Contrat API, Plan et Recette (à partir d&#39;une épic). Seules les lentilles qui ont du contenu dans le périmètre s&#39;affichent ; sur une story, <strong>Décisions (ADR)</strong> et <strong>Questions (BQO)</strong> restent toujours visibles, même vides, pour que vous puissiez y ajouter.</li><li><strong>Le contenu</strong> : par exemple une carte de décision avec son identifiant (<code>DEC-01</code>), son statut (<strong>Acceptée</strong>), sa date, son titre, son texte et ses conséquences.</li><li>Sur la lentille <strong>Cadrage projet</strong>, au niveau Projet, un bandeau indique la <strong>Prochaine couche</strong> à rédiger, ou « Cadrage projet complet — les 4 couches sont rédigées. »</li></ul><h2 id="ce-que-vous-pouvez-faire" tabindex="-1">Ce que vous pouvez faire <a class="header-anchor" href="#ce-que-vous-pouvez-faire" aria-label="Permalink to &quot;Ce que vous pouvez faire&quot;">​</a></h2><ul><li><strong>Changer de périmètre</strong> : cliquez sur un projet, une épic ou une story dans <strong>Portée</strong>. À l&#39;ouverture, l&#39;écran reprend le dernier périmètre et la dernière lentille que vous avez consultés dans ce projet ; la première fois, il se place sur la story active.</li><li><strong>Chercher</strong> : tapez dans <strong>Rechercher…</strong> (arbre) ou dans <strong>Rechercher dans la lentille…</strong> (contenu). Les termes trouvés sont surlignés.</li><li><strong>Ajouter une décision</strong> : sur une story, lentille Décisions (ADR), cliquez sur <strong>+ Ajouter une décision</strong> et remplissez le formulaire (titre, contexte, décision, conséquences, alternatives rejetées).</li><li><strong>Ajouter ou résoudre une question</strong> : sur une story, lentille Questions (BQO), <strong>+ Ajouter une question</strong> et remplissez <strong>Question</strong>, <strong>Impact</strong> et <strong>Suggestion</strong>. Sur une question ouverte d&#39;une story, <strong>Résoudre</strong>, saisissez la <strong>Réponse</strong> puis <strong>Valider</strong>. Au niveau Projet ou Épic, les questions se lisent mais ne se résolvent pas : descendez sur leur story.</li><li><strong>Compléter les documents de cadrage</strong> : sur une story, ce bouton crée les documents OPALE manquants. L&#39;écran indique combien ont été créés, ou que le cadrage est déjà complet.</li></ul><p>Sur une story, même neuve et vide, ces boutons sont toujours là : <strong>Compléter les documents de cadrage</strong> sur chaque lentille, <strong>+ Ajouter une décision</strong> et <strong>+ Ajouter une question</strong> sur leur lentille.</p><h2 id="conseils" tabindex="-1">Conseils <a class="header-anchor" href="#conseils" aria-label="Permalink to &quot;Conseils&quot;">​</a></h2><ul><li>Les facettes de filtrage (statut, impact, origine) apparaissent selon la lentille et le périmètre.</li><li>Une lentille sans contenu dans le périmètre n&#39;est pas affichée. S&#39;il n&#39;en reste aucune, l&#39;écran affiche « Aucune connaissance disponible dans ce périmètre. » : choisissez un autre élément de l&#39;arbre.</li></ul><h3 id="voir-une-tache" tabindex="-1">Voir une tâche <a class="header-anchor" href="#voir-une-tache" aria-label="Permalink to &quot;Voir une tâche&quot;">​</a></h3><p>Cliquer une tâche dans l&#39;arbre affiche sa <strong>fiche</strong> en tête : ce qui doit être fait, ce qu&#39;elle a produit, et ses commits. Une tâche ne porte ni décision ni question à elle : ce qui suit la fiche est la connaissance de sa story, et la page le dit.</p>',9)),n(t,{name:"connaissance-tache",alt:"Connaissance avec une tâche sélectionnée : sa fiche, puis la connaissance de sa story"}),e[3]||(e[3]=o('<h2 id="avec-un-agent-ia" tabindex="-1">Avec un agent IA <a class="header-anchor" href="#avec-un-agent-ia" aria-label="Permalink to &quot;Avec un agent IA&quot;">​</a></h2><p>Les agents consignent la même matière avec <code>effortless_decision_add</code>, <code>effortless_question_ask</code> et <code>effortless_question_resolve</code>, la lisent avec <code>effortless_project_tree</code> et <code>effortless_story_items</code>, et la cherchent avec <code>effortless_docs_search</code>. Le bouton <strong>Compléter les documents de cadrage</strong> correspond à <code>effortless_cadrage_docs_scaffold</code>.</p>',2))])}const _=r(l,[["render",d]]);export{q as __pageData,_ as default};
